<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Conway's Game of Life</title>
<style>
    body{
        margin:0;
        padding:0;
        display:flex;
        flex-direction:column;
        align-items:center;
        justify-content:center;
        min-height:100vh;
        background:#111;
        color:#eee;
        font-family:sans-serif;
    }
    #life{
        border:2px solid #444;
        background:#222;
        cursor:crosshair;
    }
    #controls{
        margin-top:12px;
    }
    button{
        margin:0 4px;
        padding:6px 12px;
        background:#333;
        color:#eee;
        border:none;
        border-radius:4px;
        cursor:pointer;
    }
    button:hover{
        background:#555;
    }
</style>
</head>
<body>
<canvas id="life" width="500" height="500"></canvas>
<div id="controls">
    <button id="step">Step</button>
    <button id="play">Play</button>
    <button id="random">Random</button>
    <button id="clear">Clear</button>
</div>

<script>
/* ---------- Configuration ---------- */
const W = 50;                     // grid width  (cells)
const H = 50;                     // grid height (cells)
const canvas = document.getElementById('life');
const ctx = canvas.getContext('2d');
const cellSize = Math.min(canvas.width / W, canvas.height / H);

/* ---------- State ---------- */
let board = Array.from({ length: H }, () => Array(W).fill(0));
let running = false;
let intervalId = null;

/* ---------- Rendering ---------- */
function draw() {
    ctx.fillStyle = '#222';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#0f0'; // alive cells – bright green
    for (let y = 0; y < H; ++y) {
        for (let x = 0; x < W; ++x) {
            if (board[y][x]) {
                ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
            }
        }
    }
}

/* ---------- Core Logic ---------- */
function computeNext() {
    const next = Array.from({ length: H }, () => Array(W).fill(0));

    for (let y = 0; y < H; ++y) {
        for (let x = 0; x < W; ++x) {
            let neighbors = 0;

            for (let dy = -1; dy <= 1; ++dy) {
                for (let dx = -1; dx <= 1; ++dx) {
                    if (dx === 0 && dy === 0) continue;
                    const nx = x + dx, ny = y + dy;
                    if (nx >= 0 && ny >= 0 && nx < W && ny < H) {
                        neighbors += board[ny][nx];
                    }
                }
            }

            const alive = board[y][x];
            if (alive) {
                next[y][x] = (neighbors === 2 || neighbors === 3) ? 1 : 0;
            } else {
                next[y][x] = (neighbors === 3) ? 1 : 0;
            }
        }
    }
    board = next;
}

/* ---------- Public API ---------- */
window.life = {
    w: W,
    h: H,
    get(x, y) {
        if (x < 0 || y < 0 || x >= W || y >= H) return 0;
        return board[y][x];
    },
    set(x, y, v) {
        if (x < 0 || y < 0 || x >= W || y >= H) return;
        board[y][x] = v ? 1 : 0;
        draw();
    },
    step() {
        computeNext();
        draw();
    },
    clear() {
        board = Array.from({ length: H }, () => Array(W).fill(0));
        draw();
    }
};

/* ---------- UI Controls ---------- */
document.getElementById('step').addEventListener('click', () => life.step());

document.getElementById('clear').addEventListener('click', () => life.clear());

document.getElementById('random').addEventListener('click', () => {
    for (let y = 0; y < H; ++y) {
        for (let x = 0; x < W; ++x) {
            board[y][x] = Math.random() < 0.3 ? 1 : 0;
        }
    }
    draw();
});

document.getElementById('play').addEventListener('click', () => {
    running = !running;
    const btn = document.getElementById('play');
    if (running) {
        btn.textContent = 'Pause';
        intervalId = setInterval(() => life.step(), 200);
    } else {
        btn.textContent = 'Play';
        clearInterval(intervalId);
    }
});

/* ---------- Mouse Interaction (click & drag) ---------- */
let mouseDown = false;
let drawMode = 1; // 1 → make alive, 0 → make dead

canvas.addEventListener('mousedown', e => {
    const rect = canvas.getBoundingClientRect();
    const cx = e.clientX - rect.left;
    const cy = e.clientY - rect.top;
    const x = Math.floor(cx / cellSize);
    const y = Math.floor(cy / cellSize);
    if (x < 0 || y < 0 || x >= W || y >= H) return;

    drawMode = board[y][x] ? 0 : 1; // toggle the clicked cell
    board[y][x] = drawMode;
    draw();

    mouseDown = true;
});

canvas.addEventListener('mousemove', e => {
    if (!mouseDown) return;
    const rect = canvas.getBoundingClientRect();
    const cx = e.clientX - rect.left;
    const cy = e.clientY - rect.top;
    const x = Math.floor(cx / cellSize);
    const y = Math.floor(cy / cellSize);
    if (x < 0 || y < 0 || x >= W || y >= H) return;

    if (board[y][x] !== drawMode) {
        board[y][x] = drawMode;
        draw();
    }
});

window.addEventListener('mouseup', () => { mouseDown = false; });
canvas.addEventListener('mouseleave', () => { mouseDown = false; });

/* Disable context menu on canvas */
canvas.addEventListener('contextmenu', e => e.preventDefault());

/* Initial render */
draw();
</script>
</body>
</html>
